#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   query      : [batch_size, seq_len, num_heads=48, head_dim=128] fp32
//   key        : [batch_size, seq_len, num_heads=48, head_dim=128] fp32
//   weight_q   : [num_heads=48, head_dim=128]  fp32
//   weight_k   : [num_heads=48, head_dim=128]  fp32
//   eps        : scalar fp32
//   query_norm : [batch_size, seq_len, num_heads, head_dim] fp32 (DPS)
//   key_norm   : [batch_size, seq_len, num_heads, head_dim] fp32 (DPS)
//
// head_dim and num_heads are pinned. The same kernel runs twice:
// once for (query, weight_q, query_norm), once for
// (key, weight_k, key_norm).
void run(
    const torch::Tensor& query,
    const torch::Tensor& key,
    const torch::Tensor& weight_q,
    const torch::Tensor& weight_k,
    double eps,
    torch::Tensor query_norm,
    torch::Tensor key_norm
) {
    TORCH_CHECK(query.dim() == 4, "query must be 4D [B, S, H, D]");
    TORCH_CHECK(key.dim() == 4, "key must be 4D [B, S, H, D]");
    TORCH_CHECK(weight_q.dim() == 2, "weight_q must be 2D [H, D]");
    TORCH_CHECK(weight_k.dim() == 2, "weight_k must be 2D [H, D]");
    TORCH_CHECK(query_norm.dim() == 4, "query_norm must be 4D");
    TORCH_CHECK(key_norm.dim() == 4, "key_norm must be 4D");

    const int64_t head_dim = query.size(3);
    const int64_t num_heads = query.size(2);
    TORCH_CHECK(head_dim == 128,
                "head_dim must be 128 for problem_038, got ", head_dim);
    TORCH_CHECK(num_heads == 48,
                "num_heads must be 48 for problem_038, got ", num_heads);
    TORCH_CHECK(key.size(3) == head_dim,
                "key head_dim must match query head_dim");
    TORCH_CHECK(key.size(2) == num_heads,
                "key num_heads must match query num_heads");
    TORCH_CHECK(key.size(1) == query.size(1),
                "key seq_len must match query seq_len");
    TORCH_CHECK(key.size(0) == query.size(0),
                "key batch_size must match query batch_size");
    TORCH_CHECK(weight_q.size(0) == num_heads &&
                weight_q.size(1) == head_dim,
                "weight_q must be [num_heads, head_dim]");
    TORCH_CHECK(weight_k.size(0) == num_heads &&
                weight_k.size(1) == head_dim,
                "weight_k must be [num_heads, head_dim]");
    TORCH_CHECK(query_norm.sizes() == query.sizes(),
                "query_norm shape must match query");
    TORCH_CHECK(key_norm.sizes() == key.sizes(),
                "key_norm shape must match key");

    check_fp32_contiguous_cuda(query, "query");
    check_fp32_contiguous_cuda(key, "key");
    check_fp32_contiguous_cuda(weight_q, "weight_q");
    check_fp32_contiguous_cuda(weight_k, "weight_k");
    check_fp32_contiguous_cuda(query_norm, "query_norm");
    check_fp32_contiguous_cuda(key_norm, "key_norm");

    const float eps_f32 = static_cast<float>(eps);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_038_flux_multi_head_rmsnorm_qk_launcher(
        query, weight_q, query_norm, eps_f32, stream);
    problem_038_flux_multi_head_rmsnorm_qk_launcher(
        key, weight_k, key_norm, eps_f32, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 per-head RMSNorm-QK: normalizes query and key tensors "
        "over head_dim with per-head learnable scales. Two distinct "
        "DPS outputs (query_norm, key_norm). num_heads=48, "
        "head_dim=128 pinned.");
}

#include "kernel.h"
#include <cuda_runtime.h>

// fp32 per-head RMSNorm applied to Q (or K) attention tensor.
//
//   var[b, s, h] = mean_d(x[b, s, h, d]^2)
//   x_norm[..., d] = x[..., d] * rsqrt(var + eps) * weight[h, d]
//
// num_heads = 48 and head_dim = 128 (both pinned by the problem
// definition). One CTA per (b, s, h) row of 128 elements;
// BLOCK_THREADS = head_dim = 128 so each thread handles exactly one
// element. The per-head weight table is indexed by (h, d), so the
// (B, S) row CTAs at a fixed `h` all share the same weight slice
// — strong inter-CTA reuse on the weight loads.

namespace {

constexpr int kHeadDim = 128;
constexpr int kBlockThreads = kHeadDim;
constexpr int kWarpSize = 32;
constexpr int kNumWarps = kBlockThreads / kWarpSize;  // 4

__global__ void __launch_bounds__(kBlockThreads, 8)
problem_038_rmsnorm_qk_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    float* __restrict__ x_norm,
    int num_heads,
    int seq_len,
    float eps) {

    // Grid layout: (h, s, B). Each CTA handles one (b, s, h) row of
    // head_dim elements.
    const int h = blockIdx.x;
    const int s = blockIdx.y;
    const int b = blockIdx.z;
    const int d = threadIdx.x;

    const int row_offset =
        ((b * seq_len + s) * num_heads + h) * kHeadDim;
    const int weight_offset = h * kHeadDim;

    const float xv = x[row_offset + d];
    const float wv = weight[weight_offset + d];

    // Warp-shuffle reduction of xv^2 across 32 lanes.
    float sumsq = xv * xv;
    #pragma unroll
    for (int off = kWarpSize / 2; off > 0; off >>= 1) {
        sumsq += __shfl_xor_sync(0xffffffff, sumsq, off);
    }

    // Cross-warp reduction via shared memory: lane 0 of each warp
    // contributes one partial sum; thread 0 finalises.
    __shared__ float warp_sums[kNumWarps];
    const int warp_id = d / kWarpSize;
    const int lane_id = d % kWarpSize;
    if (lane_id == 0) {
        warp_sums[warp_id] = sumsq;
    }
    __syncthreads();

    __shared__ float row_inv_rms;
    if (d == 0) {
        float total = 0.0f;
        #pragma unroll
        for (int w = 0; w < kNumWarps; ++w) {
            total += warp_sums[w];
        }
        const float mean_sq = total / static_cast<float>(kHeadDim);
        row_inv_rms = rsqrtf(mean_sq + eps);
    }
    __syncthreads();

    x_norm[row_offset + d] = xv * row_inv_rms * wv;
}

}  // namespace

void problem_038_flux_multi_head_rmsnorm_qk_launcher(
    const torch::Tensor& x,
    const torch::Tensor& weight,
    torch::Tensor& x_norm,
    float eps,
    cudaStream_t stream) {

    // x is [B, S, num_heads, head_dim] fp32.
    const int batch_size = static_cast<int>(x.size(0));
    const int seq_len = static_cast<int>(x.size(1));
    const int num_heads = static_cast<int>(x.size(2));

    dim3 grid(num_heads, seq_len, batch_size);
    dim3 block(kBlockThreads);

    problem_038_rmsnorm_qk_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        x_norm.data_ptr<float>(),
        num_heads,
        seq_len,
        eps);
}

#pragma once

#ifndef PROBLEM_038_FLUX_MULTI_HEAD_RMSNORM_QK_KERNEL_H
#define PROBLEM_038_FLUX_MULTI_HEAD_RMSNORM_QK_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the fp32 per-head RMSNorm-QK kernel.
//
// For each input tensor `x` of shape [B, S, num_heads=48, head_dim=128]
// fp32, compute:
//   var[b, s, h] = mean_d(x[b, s, h, d]^2)
//   x_norm[b, s, h, d] = x[b, s, h, d] *
//                        rsqrt(var[b, s, h] + eps) *
//                        weight[h, d]
//
// `weight` is [num_heads, head_dim] fp32 and is reused across all
// (B, S) row CTAs at the same `h`. The launcher is parameterized on
// the (input, weight, output) triple so the DPS entry can call it
// twice (once for query+weight_q → query_norm, once for key+weight_k
// → key_norm).
void problem_038_flux_multi_head_rmsnorm_qk_launcher(
    const torch::Tensor& x,
    const torch::Tensor& weight,
    torch::Tensor& x_norm,
    float eps,
    cudaStream_t stream);

#endif  // PROBLEM_038_FLUX_MULTI_HEAD_RMSNORM_QK_KERNEL_H
